54		// 原有子样交接给别人、在别处确认：它有独立于来源的持有人、地点和
55		// 保管历史（分出 → 交出 → 接收）。
56		hAt := clock.Add(time.Hour)
57		rAt := hAt.Add(time.Hour)
58		if _, err := s.Handover(HandoverInput{
