119	// assertSplitDidNotTakeEffect 断言一次保存失败的分装完全没有生效：
120	// 来源、原有子样逐项不变，两个拟创建子样仍不存在。
121	func assertSplitDidNotTakeEffect(t *testing.T, f *splitFixture) {
