135				parent.InitialQty, parent.Remaining)
136		}
137		if parent.Holder != "张三" || parent.Location != "实验室A" {
138			t.Fatalf("来源持有人和地点不应变化: %s @ %s", parent.Holder, parent.Location)
139		}
140		if len(parent.Children) != 1 || parent.Children[0] != f.existingID {
141			t.Fatalf("来源子样列表不应变化: %v", parent.Children)
142		}
143		if parent.PendingTransfer != nil || parent.Destruction != nil {
144			t.Fatalf("失败的分装不得引入待确认或销毁信息: %+v", parent)
145		}
146	
147		existing, err := f.s.GetSample(f.existingID)
148		if err != nil {
149			t.Fatalf("get existing child: %v", err)
150		}
151		if !reflect.DeepEqual(existing, f.existingBefore) {
152			t.Fatalf("原有子样不应被本次分装带动:\n before=%+v\n after =%+v",
153				f.existingBefore, existing)
154		}
155	
156		for _, id := range []string{f.c1ID, f.c2ID} {
157			if got, err := f.s.GetSample(id); !errors.Is(err, ErrNotFound) {
158				t.Fatalf("拟创建子样 %s 在失败后应仍不存在, got view=%+v err=%v", id, got, err)
159			}
160		}
161	}
162	
163	// TestSplitSaveFailureIsAtomic 覆盖入参全部合法、来源也允许分装，但本地
164	// 保存失败时的回归：Split 必须返回说明保存失败的错误（而不是成功结果，
165	// 也不能归为入参非法、状态冲突或样品不存在），整次分装不生效；恢复
166	// 保存后用原来打开的样品数据以相同编号和数量重试，应恰好成功一次。
167	func TestSplitSaveFailureIsAtomic(t *testing.T) {
168		cases := []struct {
169			name string
170			// wantErrFragment 是对应保存环节的错误文本，用于区分两类失败。
171			wantErrFragment string
172			// inject 制造一次保存失败，返回失败期间原数据所在的可读路径，
173			// 以及恢复函数（幂等，同时注册到 t.Cleanup）。
174			inject func(t *testing.T, dir, path string) (preservedPath string, restore func())
175		}{
176			{
177				name:            "数据目录无法写入",
178				wantErrFragment: "创建临时数据文件失败",
179				inject: func(t *testing.T, dir, path string) (string, func()) {
180					if err := os.Chmod(dir, 0o555); err != nil {
181						t.Fatalf("chmod dir: %v", err)
182					}
183					restored := false
184					restore := func() {
185						if restored {
186							return
187						}
188						restored = true
189						_ = os.Chmod(dir, 0o755)
190					}
191					t.Cleanup(restore)
192					return path, restore
193				},
194			},
195			{
196				name:            "既有数据文件无法被替换",
197				wantErrFragment: "替换本地样品数据文件失败",
198				inject: func(t *testing.T, dir, path string) (string, func()) {
199					// 把原数据文件移开并在同一路径放置一个目录：临时文件可以
200					// 正常写入同目录，但原子 rename 无法用文件替换一个目录。
201					aside := path + ".preserved"
202					if err := os.Rename(path, aside); err != nil {
203						t.Fatalf("move data file aside: %v", err)
204					}
205					if err := os.Mkdir(path, 0o755); err != nil {
206						t.Fatalf("place directory at data path: %v", err)
207					}
208					restored := false
209					restore := func() {
210						if restored {
211							return
212						}
213						restored = true
214						if _, err := os.Lstat(path); err == nil {
215							_ = os.RemoveAll(path)
216						}
217						_ = os.Rename(aside, path)
218					}
219					t.Cleanup(restore)
220					return aside, restore
221				},
222			},
223		}
224	
225		for _, tc := range cases {
226			t.Run(tc.name, func(t *testing.T) {
227				f := setupPriorSplit(t)
228				preservedPath, restore := tc.inject(t, f.dir, f.path)
229	
230				// 两个子样编号互不重复、尚未登记，数量合法且总量不超剩余，
231				// 来源无待确认、未销毁——分装本身完全可做，仅保存失败。
232				done, err := f.s.Split(f.in)
233				if err == nil {
234					t.Fatalf("保存失败时分装应返回错误，却得到成功结果: %+v", done)
235				}
236				if done != nil {
237					t.Fatalf("保存失败不应返回表示分装成功的样品结果: %+v", done)
238				}
239				for _, sentinel := range []error{ErrInvalid, ErrConflict, ErrNotFound} {
240					if errors.Is(err, sentinel) {
241						t.Fatalf("保存错误不应被包装为 %v，实际错误: %v", sentinel, err)
242					}
243				}
244				if !strings.Contains(err.Error(), tc.wantErrFragment) {
245					t.Fatalf("应返回 %q 对应的保存错误, got %v", tc.wantErrFragment, err)
246				}
247	
248				// 失败后立即查询：来源与原有子样停留在提交前，新子样不存在。
249				assertSplitDidNotTakeEffect(t, f)
250	
251				// 此前保存的样品文件保持原有业务内容：不能只扣了来源数量，
252				// 也不能只保存了部分子样。
253				preserved, err := os.ReadFile(preservedPath)
254				if err != nil {
255					t.Fatalf("读取原数据文件: %v", err)
256				}
257				if !bytes.Equal(preserved, f.diskBefore) {
258					t.Fatalf("保存失败改动了磁盘上的原数据文件")
259				}
260	
261				// 恢复正常文件访问：数据文件回到原路径，内容仍是提交前的状态。
262				restore()
263				disk, err := os.ReadFile(f.path)
264				if err != nil {
265					t.Fatalf("恢复后读取数据文件: %v", err)
266				}
267				if !bytes.Equal(disk, f.diskBefore) {
268					t.Fatalf("恢复后数据文件内容应与失败前一致")
269				}
270	
271				// 仍通过原来打开的样品数据，用失败时相同的子样编号和数量
272				// 重新分装：失败既没有占用编号，也没有提前扣减，应成功。
273				parent, err := f.s.Split(f.in)
274				if err != nil {
275					t.Fatalf("恢复后用相同编号和数量重新分装应成功: %v", err)
276				}
277	
278				// 返回的来源视图：只扣减 3.500，剩余 3.250；持有人地点不变。
279				if parent.InitialQty != "10.000" || parent.Remaining != "3.250" {
280					t.Fatalf("成功分装后来源数量错误: init=%s remaining=%s",
281						parent.InitialQty, parent.Remaining)
282				}
283				if parent.Holder != "张三" || parent.Location != "实验室A" {
284					t.Fatalf("分装不改变来源持有人和地点: %s @ %s",
285						parent.Holder, parent.Location)
286				}
287				wantChildren := []string{f.existingID, f.c1ID, f.c2ID}
288				if !reflect.DeepEqual(parent.Children, wantChildren) {
289					t.Fatalf("新子样应在原有子样后按请求顺序追加: got %v want %v",
290						parent.Children, wantChildren)
291				}
292				// 来源只增加本次分装应有的一条历史，原有历史原样保留。
293				if len(parent.History) != len(f.parentBefore.History)+1 {
294					t.Fatalf("来源历史应只增加一条分装记录: before=%d after=%d",
295						len(f.parentBefore.History), len(parent.History))
296				}
297				if !reflect.DeepEqual(parent.History[:len(f.parentBefore.History)],
298					f.parentBefore.History) {
299					t.Fatalf("来源原有保管历史应保持不变: %+v", parent.History)
300				}
301				last := parent.History[len(parent.History)-1]
302				if last.Kind != "split" || last.Holder != "张三" || last.Location != "实验室A" ||
303					!strings.Contains(last.Detail, f.c1ID) ||
304					!strings.Contains(last.Detail, f.c2ID) {
305					t.Fatalf("新增历史不是本次分装记录: %+v", last)
306				}
307	
308				// 两个新子样各自指向该来源，数量即请求数量，继承来源当前的
309				// 持有人和地点，各有一条分出历史；查询数量统一三位小数。
310				wantParts := []struct {
311					id, qty string
312				}{{f.c1ID, "2.125"}, {f.c2ID, "1.375"}}
313				for _, wp := range wantParts {
314					c, err := f.s.GetSample(wp.id)
315					if err != nil {
316						t.Fatalf("新子样 %s 应可查询: %v", wp.id, err)
317					}
318					if c.ParentID != f.parentID {
319						t.Fatalf("子样 %s 应指向来源 %s, got %q", wp.id, f.parentID, c.ParentID)
320					}
321					if c.InitialQty != wp.qty || c.Remaining != wp.qty {
322						t.Fatalf("子样 %s 数量错误: init=%s remaining=%s want %s",
323							wp.id, c.InitialQty, c.Remaining, wp.qty)
324					}
325					if c.Holder != "张三" || c.Location != "实验室A" {
326						t.Fatalf("子样 %s 应继承来源当前持有人和地点: %s @ %s",
327							wp.id, c.Holder, c.Location)
328					}
329					if len(c.History) != 1 || c.History[0].Kind != "split" ||
330						c.History[0].Holder != "张三" || c.History[0].Location != "实验室A" ||
331						!strings.Contains(c.History[0].Detail, f.parentID) {
332						t.Fatalf("子样 %s 的保管历史不正确: %+v", wp.id, c.History)
333					}
334				}
335	
336				// 原有子样的数量、来源和保管记录不受本次成功分装带动。
337				existing, err := f.s.GetSample(f.existingID)
338				if err != nil {
339					t.Fatal(err)
340				}
341				if !reflect.DeepEqual(existing, f.existingBefore) {
342					t.Fatalf("原有子样不应被成功分装带动:\n before=%+v\n after =%+v",
343						f.existingBefore, existing)
344				}
345	
346				// 成功的重试已正常落盘：重开后数量、子样顺序、继承关系与
347				// 各自保管历史都保持。
348				s2, err := Open(f.path)
349				if err != nil {
350					t.Fatalf("reopen after retry: %v", err)
351				}
352				reopenedParent, err := s2.GetSample(f.parentID)
353				if err != nil {
354					t.Fatal(err)
355				}
356				if reopenedParent.InitialQty != "10.000" ||
357					reopenedParent.Remaining != "3.250" ||
358					!reflect.DeepEqual(reopenedParent.Children, wantChildren) ||
359					len(reopenedParent.History) != len(parent.History) {
360					t.Fatalf("重开后来源状态错误: %+v", reopenedParent)
361				}
362				for _, wp := range wantParts {
363					c, err := s2.GetSample(wp.id)
364					if err != nil {
365						t.Fatalf("重开后子样 %s 应仍存在: %v", wp.id, err)
366					}
367					if c.ParentID != f.parentID || c.Remaining != wp.qty ||
368						c.Holder != "张三" || c.Location != "实验室A" {
369						t.Fatalf("重开后子样 %s 状态错误: %+v", wp.id, c)
370					}
371				}
372				reopenedExisting, err := s2.GetSample(f.existingID)
373				if err != nil {
374					t.Fatal(err)
375				}
376				if !reflect.DeepEqual(reopenedExisting, f.existingBefore) {
377					t.Fatalf("重开后原有子样应保持独立状态:\n before=%+v\n after =%+v",
378						f.existingBefore, reopenedExisting)
379				}
380			})
381		}
382	}
