14	// pendingConfirmFixture 是“一条已成功保存、仍待确认的交接”的测试前置状态。
15	type pendingConfirmFixture struct {
16		dir, path string
17		s         *Store
18		hAt, rAt  time.Time
19		in        ConfirmInput
20	
21		// 确认发起前的样品与交接视图，以及磁盘上已保存的数据内容；
22		// 任何保存失败之后，它们都应保持不变。
23		sampleBefore   *Sample
