42	
43		hAt := clock.Add(time.Hour)
44		rAt := hAt.Add(time.Hour) // 接收时间晚于交出时间，满足确认要求
45		if _, err := s.Handover(HandoverInput{
46			TransferID: "TR-1", SampleID: "P",
47			FromHolder: "张三", FromLocation: "实验室A",
48			ToHolder: "李四", ToLocation: "实验室B",
49			HandedOverAt: hAt,
50		}); err != nil {
51			t.Fatalf("handover: %v", err)
52		}
53	
54		disk, err := os.ReadFile(path)
55		if err != nil {
56			t.Fatalf("read persisted data: %v", err)
57		}
58		sampleBefore, err := s.GetSample("P")
59		if err != nil {
60			t.Fatal(err)
61		}
62		transferBefore, err := s.GetTransfer("TR-1")
63		if err != nil {
64			t.Fatal(err)
65		}
66		// 前置条件自检：交接已保存且处于待确认，样品仍由交出人在交出地点持有。
67		if sampleBefore.Holder != "张三" || sampleBefore.Location != "实验室A" ||
68			sampleBefore.Remaining != "6.750" || sampleBefore.PendingTransfer == nil ||
69			sampleBefore.PendingTransfer.TransferID != "TR-1" {
70			t.Fatalf("前置样品状态不正确: %+v", sampleBefore)
71		}
72		if transferBefore.Confirmed || transferBefore.ReceivedAt != nil ||
73			transferBefore.ConfirmedBy != "" {
74			t.Fatalf("前置交接不应已确认: %+v", transferBefore)
75		}
76		if !bytes.Contains(disk, []byte("TR-1")) {
77			t.Fatalf("前置交接应已落盘")
