89	// assertStillPending 断言样品与交接都停留在确认前的待确认状态：
90	// 持有人、地点、剩余量、历史、待确认详情以及交接记录逐项不变。
91	func assertStillPending(t *testing.T, s *Store, f *pendingConfirmFixture) {
92		t.Helper()
93	
94		sample, err := s.GetSample("P")
95		if err != nil {
96			t.Fatalf("get sample: %v", err)
97		}
98		if !reflect.DeepEqual(sample, f.sampleBefore) {
99			t.Fatalf("保存失败后样品状态被改动:\n before=%+v\n after =%+v",
100				f.sampleBefore, sample)
101		}
102		if sample.Holder != "张三" || sample.Location != "实验室A" {
103			t.Fatalf("保管位置应保持为交出人和交出地点, got %s @ %s",
104				sample.Holder, sample.Location)
105		}
106		if sample.PendingTransfer == nil ||
107			sample.PendingTransfer.TransferID != "TR-1" {
108			t.Fatalf("待确认详情仍应指向同一条交接 TR-1: %+v", sample.PendingTransfer)
109		}
110	
111		transfer, err := s.GetTransfer("TR-1")
112		if err != nil {
113			t.Fatalf("get transfer: %v", err)
114		}
115		if !reflect.DeepEqual(transfer, f.transferBefore) {
116			t.Fatalf("保存失败后交接记录被改动:\n before=%+v\n after =%+v",
117				f.transferBefore, transfer)
118		}
119		if transfer.Confirmed {
