126	
127	// TestConfirmSaveFailureKeepsPendingState 覆盖接收信息完全合法、但确认结果
128	// 无法保存到本地时的回归：确认必须返回保存错误而不是成功，内存与磁盘上的
129	// 保管状态都固定在确认前；恢复访问后用同一份接收信息重开重试，恰好成功
130	// 一次，重复确认仍幂等。
131	func TestConfirmSaveFailureKeepsPendingState(t *testing.T) {
132		cases := []struct {
133			name string
134			// wantErrFragment 是对应保存环节的错误文本，用于区分两类失败。
135			wantErrFragment string
136			// inject 制造一次保存失败，返回失败期间原数据所在的可读路径，
137			// 以及恢复函数（幂等，同时注册到 t.Cleanup）。
138			inject func(t *testing.T, dir, path string) (preservedPath string, restore func())
139		}{
140			{
141				name:            "数据目录无法写入",
142				wantErrFragment: "创建临时数据文件失败",
143				inject: func(t *testing.T, dir, path string) (string, func()) {
144					if err := os.Chmod(dir, 0o555); err != nil {
145						t.Fatalf("chmod dir: %v", err)
146					}
147					restored := false
148					restore := func() {
149						if restored {
150							return
151						}
152						restored = true
153						_ = os.Chmod(dir, 0o755)
154					}
155					t.Cleanup(restore)
156					return path, restore
157				},
158			},
159			{
160				name:            "既有数据文件无法被替换",
161				wantErrFragment: "替换本地样品数据文件失败",
162				inject: func(t *testing.T, dir, path string) (string, func()) {
163					// 把原数据文件移开并在同一路径放置一个目录：临时文件可以
164					// 正常写入同目录，但原子 rename 无法用文件替换一个目录。
165					aside := path + ".preserved"
166					if err := os.Rename(path, aside); err != nil {
167						t.Fatalf("move data file aside: %v", err)
168					}
169					if err := os.Mkdir(path, 0o755); err != nil {
170						t.Fatalf("place directory at data path: %v", err)
171					}
172					restored := false
173					restore := func() {
174						if restored {
175							return
176						}
177						restored = true
178						if _, err := os.Lstat(path); err == nil {
179							_ = os.RemoveAll(path)
180						}
181						_ = os.Rename(aside, path)
182					}
183					t.Cleanup(restore)
184					return aside, restore
185				},
186			},
187		}
188	
189		for _, tc := range cases {
190			t.Run(tc.name, func(t *testing.T) {
191				f := setupPendingConfirm(t)
192				preservedPath, restore := tc.inject(t, f.dir, f.path)
193	
194				// 接收人、地点、接收时间本身都满足确认要求，但本次保存失败：
195				// 必须返回错误，不能返回表示接收成功的结果。
196				done, err := f.s.Confirm(f.in)
197				if err == nil {
198					t.Fatalf("保存失败时确认应返回错误，却得到成功结果: %+v", done)
199				}
200				if done != nil {
201					t.Fatalf("保存失败不应返回成功视图: %+v", done)
202				}
203				for _, sentinel := range []error{ErrInvalid, ErrConflict, ErrNotFound} {
204					if errors.Is(err, sentinel) {
205						t.Fatalf("保存错误不应被包装为 %v，实际错误: %v", sentinel, err)
206					}
207				}
208				if !strings.Contains(err.Error(), tc.wantErrFragment) {
209					t.Fatalf("应返回 %q 对应的保存错误, got %v", tc.wantErrFragment, err)
210				}
211	
212				// 保存失败后立即查询，样品与交接都停留在确认前。
213				assertStillPending(t, f.s, f)
214	
215				// 在这次失败与下一次成功确认之间，待确认限制继续生效：
216				// 同一样品既不能分装，也不能另发起一条交接。这些冲突在校验
217				// 阶段即被拒绝，不会走到落盘，也不得影响原交接。
218				if _, err := f.s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
219					{ID: "C-1", Qty: "0.001"},
220				}}); !errors.Is(err, ErrConflict) {
221					t.Fatalf("待确认期间分装应返回 ErrConflict, got %v", err)
222				}
223				if _, err := f.s.Handover(HandoverInput{
224					TransferID: "TR-2", SampleID: "P",
225					FromHolder: "张三", FromLocation: "实验室A",
226					ToHolder: "王五", ToLocation: "实验室C",
227					HandedOverAt: f.hAt,
228				}); !errors.Is(err, ErrConflict) {
229					t.Fatalf("待确认期间另发起交接应返回 ErrConflict, got %v", err)
230				}
231				assertStillPending(t, f.s, f)
232	
233				// 此前保存的样品文件保持原有业务内容，失败没有写入半截数据。
234				preserved, err := os.ReadFile(preservedPath)
235				if err != nil {
236					t.Fatalf("读取原数据文件: %v", err)
237				}
238				if !bytes.Equal(preserved, f.diskBefore) {
239					t.Fatalf("保存失败改动了磁盘上的原数据文件")
240				}
241	
242				// 恢复正常文件访问：数据文件回到原路径，内容仍是确认前的状态。
243				restore()
244				disk, err := os.ReadFile(f.path)
245				if err != nil {
246					t.Fatalf("恢复后读取数据文件: %v", err)
247				}
248				if !bytes.Equal(disk, f.diskBefore) {
249					t.Fatalf("恢复后数据文件内容应与失败前一致")
250				}
251	
252				// 重新打开，应仍能查询到同一条待确认交接和原来的保管位置。
253				s2, err := Open(f.path)
254				if err != nil {
255					t.Fatalf("reopen: %v", err)
256				}
257				assertStillPending(t, s2, f)
258	
259				// 用失败时的同一份接收信息再次确认：成功完成一次接收。
260				done, err = s2.Confirm(f.in)
261				if err != nil {
262					t.Fatalf("恢复后用相同接收信息确认应成功: %v", err)
263				}
264				if !done.Confirmed || done.ConfirmedBy != "李四" ||
265					done.ReceivedAt == nil || !done.ReceivedAt.Equal(f.rAt) {
266					t.Fatalf("成功确认视图错误: %+v", done)
267				}
268	
269				sample, _ := s2.GetSample("P")
270				if sample.Holder != "李四" || sample.Location != "实验室B" {
271					t.Fatalf("确认后持有人和地点应改为接收人和目的地点: %+v", sample)
272				}
273				if sample.PendingTransfer != nil {
274					t.Fatalf("确认后待确认详情应消失: %+v", sample.PendingTransfer)
275				}
276				if sample.Remaining != "6.750" {
277					t.Fatalf("交接不改变剩余量, got %s", sample.Remaining)
278				}
279				// 历史只在原有记录后增加这一条接收记录。
280				if len(sample.History) != len(f.sampleBefore.History)+1 {
281					t.Fatalf("历史应只增加一条接收记录: before=%d after=%d",
282						len(f.sampleBefore.History), len(sample.History))
283				}
284				if !reflect.DeepEqual(sample.History[:len(f.sampleBefore.History)],
285					f.sampleBefore.History) {
286					t.Fatalf("原有保管历史应保持不变: %+v", sample.History)
287				}
288				last := sample.History[len(sample.History)-1]
289				if last.Kind != "transfer-in" || !last.Time.Equal(f.rAt) ||
290					last.Holder != "李四" || last.Location != "实验室B" ||
291					!strings.Contains(last.Detail, "TR-1") {
292					t.Fatalf("新增历史不是本次接收记录: %+v", last)
293				}
294				transfer, _ := s2.GetTransfer("TR-1")
295				if !transfer.Confirmed || transfer.ConfirmedBy != "李四" ||
296					transfer.ReceivedAt == nil || !transfer.ReceivedAt.Equal(f.rAt) {
297					t.Fatalf("交接查询应显示已确认并保留提交的接收时间: %+v", transfer)
298				}
299	
300				// 相同信息的重复确认仍返回原结果，不再次追加记录。
301				again, err := s2.Confirm(f.in)
302				if err != nil {
303					t.Fatalf("重复确认应幂等返回原结果: %v", err)
304				}
305				if !reflect.DeepEqual(again, done) {
306					t.Fatalf("重复确认应返回与首次成功相同的结果:\n first=%+v\n again=%+v",
307						done, again)
308				}
309				sampleAgain, _ := s2.GetSample("P")
310				if len(sampleAgain.History) != len(sample.History) {
311					t.Fatalf("重复确认不得再次追加历史: first=%d again=%d",
312						len(sample.History), len(sampleAgain.History))
313				}
314	
315				// 成功的重试已正常落盘：再次重开后状态保持。
316				s3, err := Open(f.path)
317				if err != nil {
318					t.Fatalf("reopen after retry: %v", err)
319				}
320				reopened, err := s3.GetTransfer("TR-1")
321				if err != nil {
322					t.Fatal(err)
323				}
324				if !reopened.Confirmed || reopened.ConfirmedBy != "李四" ||
325					reopened.ReceivedAt == nil || !reopened.ReceivedAt.Equal(f.rAt) {
326					t.Fatalf("重开后确认状态应保留: %+v", reopened)
327				}
328				reopenedSample, _ := s3.GetSample("P")
329				if reopenedSample.Holder != "李四" || reopenedSample.Location != "实验室B" ||
330					reopenedSample.PendingTransfer != nil ||
331					len(reopenedSample.History) != len(sample.History) {
332					t.Fatalf("重开后样品保管状态错误: %+v", reopenedSample)
333				}
334			})
335		}
336	}
